-- ════════════════════════════════════════════════════════════════════════════
--  Los límites de las 18 parroquias del Municipio Maracaibo, para el mapa.
--  Pedido por Máximo el 22/10/2026. Las que importan son las CUATRO que
--  atiende Betangar: Santa Lucía, Olegario Villalobos, Caracciolo Parra Pérez
--  y Venancio Pulgar. Las otras 14 vinieron en la misma bajada y se guardan
--  porque cuestan lo mismo, pero en el mapa van de fondo tenue.
--
--  ⛔ DE DÓNDE SALEN, Y POR QUÉ NO SE DIBUJAN A OJO. Un límite de parroquia es
--     LEGAL: con él se discute qué sector le toca a quién. Trazarlo aproximado
--     y después apoyarse en ese mapa es ponerse la falta uno mismo. Salen de
--     OpenStreetMap, fronteras administrativas de nivel 7.
--
--  ⚠️ EL NIVEL IMPORTA Y CASI CUESTA UN ERROR: las parroquias son **nivel 7**.
--     La primera búsqueda se hizo en 9 y 10 y devolvió CERO (ahí hay barrios y
--     sectores) — y uno de esos sectores **se llama «Santa Lucía», igual que
--     una parroquia**. Buscar por nombre sin mirar el nivel habría pintado un
--     barrio como si fuera la parroquia entera.
--
--  📌 SE GUARDAN EN NUESTRA BASE, no se piden al abrir el mapa. El servidor
--     público de OpenStreetMap contestó 502 «at capacity» el día que se bajó:
--     una pantalla que depende de un servidor ajeno se rompe el día que ese
--     servidor está caído.
--
--  Se guarda el CONTORNO (anillo exterior). Las 18 cerraron en un solo anillo.
-- ════════════════════════════════════════════════════════════════════════════

create table if not exists parroquias (
  nombre     text primary key,
  es_nuestra boolean not null default false,
  poligono   jsonb not null,
  puntos     integer not null,
  fuente     text not null default $f$OpenStreetMap - relacion nivel 7 - bajado 22/10/2026$f$,
  creado     timestamptz not null default now()
);

comment on table parroquias is $c$Limites de las parroquias del Municipio Maracaibo (OpenStreetMap, nivel 7). es_nuestra marca las que atiende Betangar. El poligono es [[lat,lon],...], el mismo formato que sitios_asistencia.poligono y el que esperan paso_por_poligono y Leaflet.$c$;
