alter table parroquias enable row level security;
drop policy if exists parroquias_sel on parroquias;
create policy parroquias_sel on parroquias for select to authenticated
  using (app_rol() = any (array['superadmin','admin','operador','visualizador','directivo',
                               'auditor','revisor','operativo','mecanico','rrhh']));

-- ── CONTROL POSITIVO: contra un dato INDEPENDIENTE ──────────────────────────
-- ⛔ Que el polígono cierre no prueba que esté donde dice. La comprobación de
--    verdad cruza dos fuentes que no se hablan: el límite de OpenStreetMap y el
--    nombre de parroquia que el geocodificador del PROVEEDOR le puso a cada
--    posición nuestra. Si una posición que el proveedor ubica en Olegario
--    Villalobos cae fuera del polígono de Olegario Villalobos, el polígono está
--    mal o es de otra cosa — y eso hay que saberlo ANTES de pintarlo.
do $$
declare r record; dentro int; total int; malas int := 0; detalle text := '';
begin
  for r in select nombre from parroquias where es_nuestra order by nombre loop
    select count(*) filter (where _punto_en_poligono(p.lat, p.lon,
             (select poligono from parroquias where nombre = r.nombre))),
           count(*)
      into dentro, total
      from (select lat, lon from gps_posiciones
             where ubicacion like '%' || r.nombre || '%' limit 300) p;
    if total = 0 then
      detalle := detalle || r.nombre || ': sin posiciones para comprobar; ';
    elsif dentro::numeric / total < 0.8 then
      malas := malas + 1;
      detalle := detalle || r.nombre || ': solo ' || dentro || ' de ' || total ||
                 ' adentro; ';
    else
      detalle := detalle || r.nombre || ': ' || dentro || '/' || total || ' ok; ';
    end if;
  end loop;
  if malas > 0 then
    raise exception 'CONTROL: % parroquia(s) no contienen sus propias posiciones. %',
      malas, detalle;
  end if;
  raise notice 'OK - %', detalle;
end $$;